mapper.select:
SELECT * FROM orders

    AND number LIKE CONCAT('%', #{number}, '%')
    AND phone LIKE CONCAT('%', #{phone}, '%')
    AND status = #{status}
    AND order_time > #{beginTime}
    AND order_time < #{endTime}
    user_id = #{userId}

ORDER BY order_time DESC

SELECT
    DATE(order_time) as orderDate,
    SUM(amount) as turnover
FROM orders

    AND order_time > #{beginTime}
    AND order_Time < #{endTime}
    AND status = #{status}

GROUP BY DATE(order_time)

SELECT
    DATE(order_time) AS orderDate,
    COUNT(1) AS total
FROM orders

    AND order_time > #{beginTime}
    AND order_Time < #{endTime}
    AND status = #{status}

GROUP BY orderDate

SELECT
    od.name AS name,
    SUM(od.number) AS number
FROM orders AS o JOIN order_detail AS od ON o.id = od.order_id


        AND o.status = #{status}


        AND o.order_time > #{beginTime}


        AND o.order_time < #{endTime}


GROUP BY od.name
ORDER BY number
LIMIT 0, 10
